import{_ as o,o as i,c as a,a2 as t}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"ADR-0023 — Distribuzione e aggiornamenti: dettagli (M7-WP3)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0023-distribution-and-updates-details.md","filePath":"adr/0023-distribution-and-updates-details.md"}'),d={name:"adr/0023-distribution-and-updates-details.md"};function n(c,e,r,s,l,p){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0023-—-distribuzione-e-aggiornamenti-dettagli-m7-wp3" tabindex="-1">ADR-0023 — Distribuzione e aggiornamenti: dettagli (M7-WP3) <a class="header-anchor" href="#adr-0023-—-distribuzione-e-aggiornamenti-dettagli-m7-wp3" aria-label="Permalink to &quot;ADR-0023 — Distribuzione e aggiornamenti: dettagli (M7-WP3)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>proposta (le pipeline non sono mai state eseguite: vedi &quot;Verificato e non&quot;)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-27</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§4 (modulo <code>updater</code>, supply chain, release), tabella rischi (scheme <code>memobrain://</code>), M7; ADR-0001</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no. Chiarisce: chiave di firma del manifest distinta dai certificati di code signing</td></tr></tbody></table><blockquote><p><strong>Nota (ADR-0051, accettata il 2026-11-20 e recepita in <code>Specifications.md</code> v1.8).</strong> Le parti che dicono «Wails v2», il template NSIS di Wails e <code>wails.json</code> sono superate: il client si costruisce con <code>scripts/build-desktop-bin.sh</code> e <code>scripts/release/build-desktop.sh</code> su Wails v3.1.0, e i metadati del prodotto stanno in <code>apps/desktop/build/project.json</code> (vedi <a href="./../release/"><code>docs/release/README.md</code></a>). Il manifest firmato e gli installer firmati di questo ADR non sono mai stati attivati. Il testo qui sotto è storico e non cambia.</p></blockquote><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>M7 richiede installer firmati, aggiornamento automatico dal canale firmato, immagini OCI e chart Helm. Mancano le credenziali reali (Authenticode, Apple Developer ID, cosign, chiave del manifest): la pipeline deve firmare quando i segreti ci sono e fallire in modo esplicito quando mancano.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p><strong>Manifest.</strong> <code>manifest.json</code> (schema 1: <code>channel</code>, <code>version</code>, <code>sequence</code>, <code>min_version</code>, <code>released_at</code>, <code>notes</code>, <code>artifacts[]</code> con <code>os</code>, <code>arch</code>, <code>kind</code>, <code>url</code>, <code>sha256</code>, <code>size</code>) più <code>manifest.json.sig</code>, firma ed25519 detached in base64 sui byte esatti del file preceduti da un separatore di dominio (<code>memobrain-update-manifest-v1\\n</code>). Codice in <code>shared/go/updatemanifest</code>, usato dal client (<code>apps/desktop/internal/updater</code>) e dal tool <code>tools/release</code> (<code>gen-manifest</code>, <code>sign-manifest</code>, <code>verify-manifest</code>, <code>gen-key</code>, <code>pubkey</code>). Il client scarica manifest e firma (limiti 256 KiB / 1 KiB) e <strong>verifica la firma prima di fare il parse</strong>; l&#39;URL base è compilato (<code>ManifestBaseURL</code>) e il canale è nel percorso (<code>stable/</code>, <code>beta/</code>).</p><p><strong>Chiavi.</strong> La chiave pubblica è incorporata con ldflags (<code>updater.PublicKeyB64</code>); se vuota vale la chiave di <strong>sviluppo</strong>, derivata da una frase pubblica (inutile come segreto). <code>build-desktop.sh --release</code> rifiuta di compilare senza <code>UPDATE_PUBLIC_KEY</code>. La privata sta nel segreto <code>UPDATE_SIGNING_KEY</code> e in una copia offline. Rotazione e compromissione: <code>docs/release/README.md</code>.</p><p><strong>Anti-rollback.</strong> (1) <code>sequence</code> cresce a ogni manifest di un canale (numero di run del workflow); il client ne persiste il massimo per canale (<code>updater.json</code>, scritto solo dopo la verifica della firma) e rifiuta valori inferiori (replay). (2) <code>min_version</code> è una soglia di revoca: il client ne persiste il massimo e rifiuta manifest con <code>version</code> sotto la soglia; un client sotto la soglia vede l&#39;aggiornamento come obbligatorio. (3) Mai offerta una versione <code>&lt;=</code> di quella in esecuzione (semver con pre-release). (4) Un manifest di un altro canale è rifiutato. Il file di stato è locale: chi lo cancella perde la protezione, ma resta vincolato alla firma.</p><p><strong>Download.</strong> Solo <code>https</code> (<code>http</code> ammesso solo su loopback, per test); la dimensione firmata è il limite assoluto, l&#39;hash SHA-256 è controllato prima del <code>rename</code> atomico in <code>&lt;data&gt;/updates/</code>. Nome del file generato, mai preso dall&#39;URL. Resume non implementato.</p><p><strong>Privacy e opt-out.</strong> Le uniche richieste sono due GET (manifest, firma) con User-Agent fisso <code>MemobrainUpdater</code>, senza versione, cookie o identificativi. Controllo all&#39;avvio (dopo 45 s) e ogni 24 h + jitter fino a 2 h; impostazioni: canale e controllo automatico (il comando <code>update:check</code> funziona sempre). Disattivazione amministrativa: variabile <code>MEMOBRAIN_UPDATES=off</code> o ldflag <code>DisabledByBuild=1</code> (pacchetti gestiti da un package manager). Le build di sviluppo (versione non semver) non controllano. Non è stata aggiunta una chiave <code>updates.*</code> al Config Profile: richiede di aggiornare le due copie dello schema e il test di parità, fuori dal perimetro del WP.</p><p><strong>Applicazione per OS.</strong></p><table tabindex="0"><thead><tr><th>Piattaforma</th><th>Artefatto</th><th>Cosa fa il client</th><th>Automazione</th></tr></thead><tbody><tr><td>Windows</td><td><code>nsis</code> (.exe)</td><td>script <code>cmd</code> che, dopo l&#39;uscita dell&#39;app, esegue l&#39;installer <code>/S</code> e rilancia l&#39;app</td><td>sì (UAC: l&#39;installer chiede privilegi di amministratore)</td></tr><tr><td>macOS</td><td><code>dmg</code></td><td>script helper: attende l&#39;uscita, monta il dmg, <code>codesign --verify</code> e <code>spctl --assess</code>, sostituisce il <code>.app</code> tenendo il vecchio fino al successo, rilancia; se il bundle non è scrivibile o un controllo fallisce apre il dmg</td><td>sì, con ripiego manuale</td></tr><tr><td>Linux AppImage</td><td><code>appimage</code></td><td>se <code>$APPIMAGE</code> è impostata sostituisce il file in loco (rename atomico)</td><td>sì, riavvio manuale</td></tr><tr><td>Linux <code>.deb</code> / altro</td><td><code>deb</code></td><td>mostra il file verificato nel file manager</td><td>no (serve root)</td></tr></tbody></table><p><strong>Installer.</strong> Wails v2: universale <code>.app</code> per macOS; NSIS dal template Wails (registra <code>memobrain://</code> da <code>wails.json</code>, come da ADR-0001) con <code>signtool</code> attivato da <code>MEMOBRAIN_SIGNTOOL_CMD</code>; <code>.dmg</code> con <code>hdiutil</code>, firma <code>codesign</code> (hardened runtime, <code>entitlements.plist</code> vuoto), <code>notarytool</code> e <code>stapler</code>; Linux <code>.deb</code> (nfpm) e AppImage (appimagetool), <code>.desktop</code> con <code>MimeType=x-scheme-handler/memobrain;</code> e metadata AppStream. Il Bundle ID macOS è <code>dev.memobrain.desktop</code> (prima <code>com.wails.memobrain</code>).</p><p><strong>Cloud.</strong> Immagine multi-arch su GHCR, firma <code>cosign</code> keyless, SBOM e provenienza BuildKit; chart Helm completo (HPA, PDB, topology spread, probe, preStop, NetworkPolicy, ExternalSecret, Ingress HTTP e gRPC, <code>values.schema.json</code>) pubblicato come artefatto OCI firmato; <code>deploy/compose</code> per l&#39;on-premise. Corretto il <code>Dockerfile</code> (mancava <code>api/config-profile.schema.json</code>: la build della Web UI falliva).</p><h2 id="verificato-e-non" tabindex="-1">Verificato e non <a class="header-anchor" href="#verificato-e-non" aria-label="Permalink to &quot;Verificato e non&quot;">​</a></h2><ul><li><strong>Verificato qui</strong>: test Go (firma valida/invalida/manomessa/chiave errata, downgrade, replay, hash, dimensione, server <code>httptest</code> end to end, apply per OS con runner finti) e UI con mock; <code>wails build</code> universale macOS e <code>.dmg</code> non firmato; installer NSIS per Windows cross-compilato (non eseguito); <code>helm lint</code>/<code>template</code> e deploy su k3d usa e getta; <code>docker compose</code> con avvio completo e <code>/readyz</code>; <code>actionlint</code>.</li><li><strong>Aggiornamento M10 (ADR-0031):</strong> i workflow sono stati riscritti (un solo workflow per tag, canale non firmato, matrice con Windows e Linux arm64); la validazione resta <code>actionlint</code> e prove locali, ancora <strong>nessuna esecuzione su GitHub</strong>.</li><li><strong>Non verificato</strong>: esecuzione dei workflow; firma Authenticode, firma/notarizzazione Apple, cosign, attestazioni; build Linux, <code>.deb</code>, AppImage; l&#39;applicazione reale dell&#39;aggiornamento su Windows, macOS e Linux; TLS e gRPC attraverso il proxy; HPA con carico.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Aggiornatore terzo (Sparkle, go-update, Squirrel)</strong> — scartato: aggiunge un canale di fiducia e dipendenze per OS; il manifest firmato è piccolo e testabile.</li><li><strong>Firma con i certificati di code signing</strong> — scartata: Authenticode/Apple non coprono il manifest e legano la fiducia ai fornitori; ed25519 è semplice e ruotabile.</li><li><strong>Solo timestamp o scadenza anti-replay</strong> — scartata: richiede orologi affidabili; il <code>sequence</code> monotono non dipende dall&#39;ora.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><p>Servono i segreti elencati in <code>docs/release/secrets.md</code>; il primo RC deve esercitare l&#39;intera catena su macchine pulite. La regola anti-rollback impedisce i downgrade automatici per scelta. Il <code>sequence</code> basato sul numero di run richiede di non rieseguire vecchi tag. Da rivalutare: resume dei download, aggiornamento in-place su Linux <code>.deb</code> tramite repository APT.</p>',21)])])}const g=o(d,[["render",n]]);export{u as __pageData,g as default};
